function NotificationsPage({notify}){
  const [items,setItems]=useState(profileViewNotifications); const [tab,setTab]=useState('All Views'); const [query,setQuery]=useState(''); const [page,setPage]=useState(1); const [client,setClient]=useState(null); const [menuId,setMenuId]=useState(null); const pageSize=6
  const filtered=items.filter(item=>(tab==='All Views'||(tab==='New'&&item.new)||(tab==='Seen'&&!item.new))&&`${item.name} ${item.role}`.toLowerCase().includes(query.toLowerCase()))
  const pages=Math.max(1,Math.ceil(filtered.length/pageSize)); const shown=filtered.slice((page-1)*pageSize,page*pageSize); const newCount=items.filter(item=>item.new).length
  useEffect(()=>setPage(1),[tab,query])
  const markAllSeen=()=>{setItems(rows=>rows.map(item=>({...item,new:false})));notify('All profile views marked as seen')}
  const openClient=item=>{setClient(item);setItems(rows=>rows.map(row=>row.id===item.id?{...row,new:false}:row));setMenuId(null)}
  const removeItem=id=>{setItems(rows=>rows.filter(item=>item.id!==id));setMenuId(null);notify('Notification removed')}
  return <section className="notifications-page"><div className="notifications-title"><div><h1>Notifications</h1><p>See who viewed your profile. These are potential new clients.</p></div><div><button type="button" onClick={markAllSeen} disabled={!newCount}><Icon name="check"/>Mark all as seen</button><button type="button" className={tab==='New'?'is-active':''} onClick={()=>setTab(value=>value==='New'?'All Views':'New')} aria-label="Toggle new views filter"><Icon name="filter"/></button></div></div>
    <div className="notification-stats">{[['users','violet','128','Total Profile Views','All time'],['star','purple',String(newCount),'New Views Today','↑ 12% from yesterday'],['calendar','blue','56','Views This Week','↑ 18% from last week'],['user','green','42','Unique Clients','All time']].map(([icon,tone,value,label,note])=><article key={label}><i className={tone}><Icon name={icon} size={27}/></i><div><span>{label}</span><strong>{value}</strong><small className={note.startsWith('↑')?'is-up':''}>{note}</small></div></article>)}</div>
    <div className="notification-table"><header><div className="notification-tabs">{[['All Views',items.length],['New',newCount],['Seen',items.length-newCount]].map(([label,count])=><button type="button" className={tab===label?'is-active':''} onClick={()=>setTab(label)} key={label}>{label}<b>{count}</b></button>)}</div><label><Icon name="search"/><input value={query} onChange={event=>setQuery(event.target.value)} placeholder="Search clients..."/></label></header><div className="notification-rows">{shown.map(item=><article className={item.new?'is-new':''} key={item.id}><span className="notification-dot"/><i className={item.tone||''}>{item.initials}</i><div className="notification-person"><strong>{item.name}</strong><p>Viewed your profile {item.new&&<b>New Client</b>}</p><small>{item.role}</small></div><div className="notification-time"><strong>{item.relative}</strong><span>{item.date}<i/> {item.time}</span></div><button type="button" className="view-client" onClick={()=>openClient(item)}><Icon name="eye" size={15}/>View Client</button><div className="notification-more"><button type="button" onClick={()=>setMenuId(value=>value===item.id?null:item.id)} aria-label={`Options for ${item.name}`}><Icon name="more"/></button>{menuId===item.id&&<div><button type="button" onClick={()=>{setItems(rows=>rows.map(row=>row.id===item.id?{...row,new:!row.new}:row));setMenuId(null)}}>{item.new?'Mark as seen':'Mark as new'}</button><button type="button" onClick={()=>removeItem(item.id)}>Remove</button></div>}</div><span className="notification-state"/></article>)}{!shown.length&&<div className="notification-empty"><i><Icon name="bell"/></i><strong>No profile views found</strong><p>Try changing your active filter or search.</p></div>}</div></div>
    {pages>1&&<nav className="notification-pagination" aria-label="Notifications pagination"><button type="button" disabled={page===1} onClick={()=>setPage(value=>value-1)}><Icon name="chevronLeft"/></button>{Array.from({length:pages},(_,index)=>index+1).map(number=><button type="button" className={page===number?'is-active':''} onClick={()=>setPage(number)} key={number}>{number}</button>)}<button type="button" disabled={page===pages} onClick={()=>setPage(value=>value+1)}><Icon name="chevronRight"/></button></nav>}
    {client&&<div className="provider-action-backdrop" onMouseDown={event=>event.target===event.currentTarget&&setClient(null)}><div className="provider-action-modal notification-client-modal"><button type="button" className="action-modal-close" onClick={()=>setClient(null)}>×</button><div className={`notification-client-avatar ${client.tone||''}`}>{client.initials}</div><h2>{client.name}</h2><p>{client.role}</p><div><span><Icon name="eye"/>Viewed your profile</span><span><Icon name="calendar"/>{client.date} at {client.time}</span><span><Icon name="location"/>India</span></div><footer><button type="button" onClick={()=>setClient(null)}>Close</button><button type="button" onClick={()=>{setClient(null);notify(`Message composer opened for ${client.name}`)}}><Icon name="message" size={15}/>Send Message</button></footer></div></div>}
  </section>
}

