function MessagesPage({notify}){
  const [selected,setSelected]=useState(1); const [tab,setTab]=useState('All'); const [search,setSearch]=useState(''); const [scope,setScope]=useState('All Conversations'); const [draft,setDraft]=useState(''); const [messages,setMessages]=useState(initialChatMessages); const [detailsOpen,setDetailsOpen]=useState(false); const [contacts,setContacts]=useState(messageContacts); const [modal,setModal]=useState(null); const [favourites,setFavourites]=useState([]); const [newChat,setNewChat]=useState({name:'',service:''}); const fileRef=useRef(null); const imageRef=useRef(null)
  const contact=contacts.find(item=>item.id===selected)||contacts[0]
  const filtered=contacts.filter(item=>(tab==='All'&&!item.archived||(tab==='Unread'&&item.unread&&!item.archived)||(tab==='Archived'&&item.archived))&&(scope==='All Conversations'||(scope==='Active Orders'&&item.service!=='Domain & Hosting')||(scope==='New Enquiries'&&item.id>=7))&&`${item.name} ${item.preview} ${item.service}`.toLowerCase().includes(search.toLowerCase()))
  const chat=messages[selected]||[['in',contact.preview,contact.time]]
  const sendMessage=event=>{event.preventDefault();if(!draft.trim())return;setMessages(current=>({...current,[selected]:[...(current[selected]||[]),['out',draft.trim(),'Now']]}));setDraft('');notify('Message sent successfully')}
  const createConversation=event=>{event.preventDefault();if(!newChat.name.trim()||!newChat.service.trim())return;const id=Date.now();const name=newChat.name.trim();const initials=name.split(' ').map(word=>word[0]).join('').slice(0,2).toUpperCase();setContacts(rows=>[{id,initials,name,service:newChat.service.trim(),preview:'New conversation started',time:'Now',online:true},...rows]);setMessages(current=>({...current,[id]:[]}));setSelected(id);setTab('All');setModal(null);setNewChat({name:'',service:''});notify(`Conversation with ${name} created`)}
  const archiveConversation=()=>{setContacts(rows=>rows.map(item=>item.id===selected?{...item,archived:true,unread:0}:item));setTab('Archived');setDetailsOpen(false);notify(`${contact.name}'s conversation archived`)}
  const chooseFile=(event,type)=>{const file=event.target.files?.[0];if(!file)return;setDraft(value=>`${value}${value?' ':''}${type==='image'?'🖼️':'📎'} ${file.name}`);notify(`${file.name} attached`);event.target.value=''}
  return <section className="messages-page">
    <div className="messages-title"><div><h1>Messages</h1><p>Communicate with your clients and manage your conversations.</p></div><div><label><select value={scope} onChange={event=>setScope(event.target.value)} aria-label="Conversation type"><option>All Conversations</option><option>Active Orders</option><option>New Enquiries</option></select></label><label className="message-search"><Icon name="search" size={16}/><input value={search} onChange={event=>setSearch(event.target.value)} placeholder="Search messages..."/></label><button type="button" className="message-filter" onClick={()=>setTab(value=>value==='Unread'?'All':'Unread')} aria-label="Toggle unread conversations"><Icon name="sliders" size={17}/></button><button type="button" className="new-message" onClick={()=>setModal('new')}><Icon name="compose" size={16}/>New Message</button></div></div>
    <div className={`message-workspace ${detailsOpen?'details-open':''}`}>
      <aside className="conversation-panel"><div className="conversation-tabs">{[['All',contacts.filter(item=>!item.archived).length],['Unread',contacts.filter(item=>item.unread&&!item.archived).length],['Archived',contacts.filter(item=>item.archived).length]].map(([label,count])=><button type="button" className={tab===label?'is-active':''} onClick={()=>setTab(label)} key={label}>{label}{count>0&&<b>{count}</b>}</button>)}</div><div className="conversation-list">{filtered.map(item=><button type="button" key={item.id} className={selected===item.id?'is-selected':''} onClick={()=>{setSelected(item.id);setDetailsOpen(false);setContacts(rows=>rows.map(row=>row.id===item.id?{...row,unread:0}:row))}}><i className={item.tone||''}>{item.initials}<span className={item.online?'is-online':''}/></i><div><strong>{item.name}<time>{item.time}</time></strong><p>{item.preview}</p><small>{item.service}</small></div>{item.unread&&<b>{item.unread}</b>}</button>)}{!filtered.length&&<div className="conversation-empty"><Icon name="message"/><span>No conversations found</span></div>}</div></aside>
      <main className="chat-panel"><header><div className="chat-person"><i>{contact.initials}<span className={contact.online?'is-online':''}/></i><div><strong>{contact.name}</strong><p>{contact.service}<span/>Order #BK25052401</p></div></div><div className="chat-actions"><button type="button" onClick={()=>setModal('call')} aria-label="Voice call"><Icon name="phone"/></button><button type="button" onClick={()=>setModal('video')} aria-label="Video call"><Icon name="videoCall"/></button><button type="button" className="details-toggle" onClick={()=>setDetailsOpen(value=>!value)} aria-label="Conversation details"><Icon name="more"/></button></div></header><div className="chat-scroll"><div className="chat-date"><span>28 August, 2026</span></div>{chat.length?chat.map(([side,text,time],index)=><div className={`chat-message ${side}`} key={`${time}-${index}`}>{side==='in'&&<i>{contact.initials}</i>}<div><p>{text}</p><time>{time}{side==='out'&&<b>✓✓</b>}</time></div></div>):<div className="chat-welcome"><Icon name="message"/><strong>Start your conversation</strong><p>Send a message to {contact.name} about {contact.service}.</p></div>}</div><form className="message-composer" onSubmit={sendMessage}><textarea value={draft} onChange={event=>setDraft(event.target.value)} placeholder="Type your message..." rows="2"/><input ref={fileRef} type="file" hidden onChange={event=>chooseFile(event,'file')}/><input ref={imageRef} type="file" accept="image/*" hidden onChange={event=>chooseFile(event,'image')}/><div><span><button type="button" onClick={()=>fileRef.current?.click()} aria-label="Attach file"><Icon name="paperclip"/></button><button type="button" onClick={()=>imageRef.current?.click()} aria-label="Add image"><Icon name="image"/></button><button type="button" onClick={()=>setDraft(value=>`${value}${value?' ':''}😊`)} aria-label="Add emoji"><Icon name="smile"/></button></span><button type="submit" disabled={!draft.trim()} aria-label="Send message"><Icon name="send"/></button></div></form></main>
      <aside className="message-details"><button type="button" className="details-close" onClick={()=>setDetailsOpen(false)} aria-label="Close details">×</button><article className="client-card"><header><i>{contact.initials}<span className={contact.online?'is-online':''}/></i><div><strong>{contact.name}</strong><p>Client</p></div><button type="button" className={favourites.includes(selected)?'is-favourite':''} onClick={()=>setFavourites(value=>value.includes(selected)?value.filter(id=>id!==selected):[...value,selected])} aria-label="Favourite client"><Icon name="star"/></button><button type="button" onClick={()=>setModal('client')} aria-label="More client options"><Icon name="more"/></button></header><ul><li><Icon name="mail"/>johndeo@email.com</li><li><Icon name="phone"/>+91 98765 43210</li><li><Icon name="location"/>Jaipur, Rajasthan, India</li><li><Icon name="clock"/>10:30 AM Local Time</li></ul></article><article className="order-card"><header><strong>Order Details</strong><button type="button" onClick={()=>setModal('order')}>View Order</button></header><div className="message-order"><i><Icon name="services"/></i><div><strong>{contact.service}</strong><button type="button" className="order-link" onClick={()=>setModal('order')}>Order #BK25052401</button><span>Completed</span></div></div><dl><div><dt>Ordered On</dt><dd>20 Aug, 2026</dd></div><div><dt>Amount</dt><dd>₹12,500</dd></div></dl></article><article className="conversation-info"><strong>Conversation Info</strong><dl><dt>First Message</dt><dd>28 Aug, 2026</dd><dt>Total Messages</dt><dd>{chat.length}</dd><dt>Status</dt><dd><span>{contact.archived?'Archived':'Active'}</span></dd><dt>Last Message</dt><dd>10:30 AM, Today</dd></dl><button type="button" onClick={archiveConversation} disabled={contact.archived}><Icon name="archive"/>{contact.archived?'Conversation Archived':'Archive Conversation'}</button></article></aside>
    </div>
    {modal&&<div className="provider-action-backdrop" onMouseDown={event=>event.target===event.currentTarget&&setModal(null)}><div className="provider-action-modal"><button type="button" className="action-modal-close" onClick={()=>setModal(null)}>×</button>{modal==='new'?<form onSubmit={createConversation}><i><Icon name="compose"/></i><h2>Start a new conversation</h2><p>Choose a client and service to open a fresh message thread.</p><label>Client name<input autoFocus value={newChat.name} onChange={event=>setNewChat({...newChat,name:event.target.value})} placeholder="e.g. Aarav Mehta"/></label><label>Service<input value={newChat.service} onChange={event=>setNewChat({...newChat,service:event.target.value})} placeholder="e.g. Website Design"/></label><footer><button type="button" onClick={()=>setModal(null)}>Cancel</button><button type="submit" disabled={!newChat.name.trim()||!newChat.service.trim()}>Create Conversation</button></footer></form>:<><i><Icon name={modal==='call'?'phone':modal==='video'?'videoCall':modal==='order'?'services':'user'}/></i><h2>{modal==='call'?`Voice call with ${contact.name}`:modal==='video'?`Video call with ${contact.name}`:modal==='order'?'Order #BK25052401':`${contact.name} options`}</h2><p>{modal==='call'||modal==='video'?`${contact.name} is online and ready to connect.`:modal==='order'?`${contact.service} · Completed · ₹12,500`:'Manage this client or open their public profile.'}</p><footer><button type="button" onClick={()=>setModal(null)}>Cancel</button><button type="button" onClick={()=>{notify(modal==='call'?'Voice call started':modal==='video'?'Video call started':modal==='order'?'Order timeline opened':'Client profile opened');setModal(null)}}>{modal==='call'?'Start Call':modal==='video'?'Start Video':modal==='order'?'View Timeline':'Open Profile'}</button></footer></>}</div></div>}
  </section>
}

